import React, { useEffect } from 'react';
import { View, StyleSheet, Platform } from 'react-native';
import Animated, {
  useSharedValue, useAnimatedStyle, withRepeat, withTiming,
  withSpring, withSequence, cancelAnimation, Easing,
} from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';
import { BlurView } from 'expo-blur';
import { useTheme } from '../context/ThemeContext';

const PARTICLE_COUNT = 12;
const RING_COUNT = 3;
const WAVE_BAR_COUNT = 16;

function generateParticles(count) {
  return Array.from({ length: count }, (_, i) => ({
    id: i,
    size: 3 + Math.random() * 5,
    initialX: Math.random() * 200 - 100,
    initialY: Math.random() * 200 - 100,
    duration: 3000 + Math.random() * 4000,
    delay: Math.random() * 3000,
    drift: Math.random() * 20 - 10,
  }));
}

function generateWaveBars(count) {
  return Array.from({ length: count }, (_, i) => ({
    id: i,
    angle: (i / count) * Math.PI,
    width: 3 + Math.random() * 2,
  }));
}

const particles = generateParticles(PARTICLE_COUNT);
const waveBars = generateWaveBars(WAVE_BAR_COUNT);

export default function VoiceOrb({ state = 'idle', size = 280, colors }) {
  const { colors: themeColors } = useTheme();
  const c = colors || themeColors;

  const pulse = useSharedValue(0.96);
  const glow = useSharedValue(0.6);
  const ringScales = useSharedValue([0.8, 0.8, 0.8]);
  const ringOpacities = useSharedValue([0.5, 0.3, 0.15]);
  const particleOffsets = useSharedValue(particles.map(() => 0));
  const waveHeights = useSharedValue(waveBars.map(() => 0.2));
  const blobOffsets = useSharedValue([0, 0, 0]);
  const rotation = useSharedValue(0);

  const halfSize = size / 2;

  useEffect(() => {
    cancelAnimation(pulse);
    cancelAnimation(glow);
    cancelAnimation(ringScales);
    cancelAnimation(ringOpacities);
    cancelAnimation(rotation);

    switch (state) {
      case 'idle':
        pulse.value = withRepeat(withTiming(1, { duration: 2000, easing: Easing.inOut(Easing.sin) }), -1, true);
        glow.value = withRepeat(withTiming(0.5, { duration: 2000, easing: Easing.inOut(Easing.sin) }), -1, true);
        ringScales.value = [0.85, 0.85, 0.85];
        ringOpacities.value = [0.3, 0.15, 0.08];
        rotation.value = withRepeat(withTiming(360, { duration: 20000, easing: Easing.linear }), -1, false);
        break;

      case 'listening':
        pulse.value = withRepeat(withTiming(1.05, { duration: 600, easing: Easing.inOut(Easing.sin) }), -1, true);
        glow.value = withRepeat(withTiming(0.9, { duration: 600, easing: Easing.inOut(Easing.sin) }), -1, true);
        ringScales.value = withRepeat(withSequence(
          withTiming(1.15, { duration: 800 }),
          withTiming(0.9, { duration: 800 }),
        ), -1, false);
        rotation.value = withRepeat(withTiming(360, { duration: 15000, easing: Easing.linear }), -1, false);
        break;

      case 'speaking': {
        pulse.value = withRepeat(withTiming(1.08, { duration: 400, easing: Easing.inOut(Easing.sin) }), -1, true);
        glow.value = withRepeat(withTiming(1, { duration: 400, easing: Easing.inOut(Easing.sin) }), -1, true);

        const expand = withTiming(1.3, { duration: 300 });
        const contract = withTiming(1.05, { duration: 500 });
        ringScales.value = withRepeat(withSequence(expand, contract), -1, false);

        const fadeUp = withTiming(0.6, { duration: 300 });
        const fadeDown = withTiming(0.2, { duration: 500 });
        ringOpacities.value = withRepeat(withSequence(fadeUp, fadeDown), -1, false);

        waveHeights.value = waveBars.map(() => withRepeat(withTiming(0.9 + Math.random() * 0.1, { duration: 300 + Math.random() * 200 }), -1, true));
        rotation.value = withRepeat(withTiming(360, { duration: 12000, easing: Easing.linear }), -1, false);
        break;
      }

      case 'thinking':
        pulse.value = withRepeat(withTiming(0.98, { duration: 1200, easing: Easing.inOut(Easing.sin) }), -1, true);
        glow.value = withRepeat(withTiming(0.7, { duration: 1200, easing: Easing.inOut(Easing.sin) }), -1, true);
        ringScales.value = [0.9, 0.9, 0.9];
        ringOpacities.value = [0.2, 0.1, 0.05];
        rotation.value = withRepeat(withTiming(-360, { duration: 25000, easing: Easing.linear }), -1, false);
        break;
    }

    return () => {
      cancelAnimation(pulse);
      cancelAnimation(glow);
      cancelAnimation(rotation);
    };
  }, [state]);

  useEffect(() => {
    particleOffsets.value = particles.map((p) =>
      withRepeat(withSequence(
        withTiming(1, { duration: p.duration, easing: Easing.inOut(Easing.sin) }),
        withTiming(0, { duration: p.duration, easing: Easing.inOut(Easing.sin) }),
      ), -1, false)
    );
  }, []);

  const orbStyle = useAnimatedStyle(() => ({
    width: size,
    height: size,
    borderRadius: halfSize,
    transform: [{ scale: pulse.value }],
  }));

  const glowStyle = useAnimatedStyle(() => ({
    width: size * 1.6,
    height: size * 1.6,
    borderRadius: size * 0.8,
    opacity: glow.value * 0.35,
    position: 'absolute',
  }));

  const ringStyles = Array.from({ length: RING_COUNT }, (_, i) =>
    useAnimatedStyle(() => ({
      width: size * ringScales.value?.[i] ?? 0.85,
      height: size * ringScales.value?.[i] ?? 0.85,
      borderRadius: (size * (ringScales.value?.[i] ?? 0.85)) / 2,
      opacity: ringOpacities.value?.[i] ?? 0.2,
      position: 'absolute',
      borderWidth: 1.5,
      borderColor: c.primary + '60',
    }))
  );

  const particleStyles = particles.map((p, i) =>
    useAnimatedStyle(() => {
      const progress = particleOffsets.value?.[i] ?? 0;
      const yOffset = -80 * progress;
      const xDrift = p.drift * Math.sin(progress * Math.PI * 2);
      const fadeOut = 1 - progress * 0.6;
      return {
        width: p.size,
        height: p.size,
        borderRadius: p.size / 2,
        backgroundColor: c.primary,
        opacity: 0.6 * fadeOut,
        position: 'absolute',
        left: halfSize + p.initialX + xDrift - p.size / 2,
        top: halfSize + p.initialY + yOffset - p.size / 2,
      };
    })
  );

  const waveStyles = waveBars.map((bar, i) =>
    useAnimatedStyle(() => {
      const h = (waveHeights.value?.[i] ?? 0.2) * size * 0.25;
      const angle = bar.angle;
      const radius = halfSize + 8;
      const x = halfSize + Math.cos(angle) * radius - bar.width / 2;
      const y = halfSize + Math.sin(angle) * radius;
      return {
        width: bar.width,
        height: Math.max(4, h),
        backgroundColor: c.primary + 'CC',
        borderRadius: bar.width / 2,
        position: 'absolute',
        left: x,
        top: y,
        transformOrigin: 'bottom center',
      };
    })
  );

  const rotateStyle = useAnimatedStyle(() => ({
    transform: [{ rotate: `${rotation.value}deg` }],
  }));

  const isSpeaking = state === 'speaking';
  const isListening = state === 'listening';
  const isThinking = state === 'thinking';

  return (
    <View style={[styles.wrapper, { width: size * 2, height: size * 2, marginLeft: -size / 2, marginTop: -size / 2 }]}>
      <Animated.View style={[glowStyle, { backgroundColor: c.primary + '40' }]} />

      {ringStyles.map((style, i) => (
        <Animated.View key={`ring-${i}`} style={[style, { top: -(size * (ringScales.value?.[i] ?? 0.85) - size) / 2, left: -(size * (ringScales.value?.[i] ?? 0.85) - size) / 2 }]} />
      ))}

      {isSpeaking && waveStyles.map((style, i) => (
        <Animated.View key={`wave-${i}`} style={style} />
      ))}

      <Animated.View style={[styles.liquidContainer, { width: size, height: size, borderRadius: halfSize }, rotateStyle]}>
        <View style={[StyleSheet.absoluteFill, { borderRadius: halfSize, overflow: 'hidden' }]}>
          <LiquidBlob size={size} color1={c.primary} color2={c.secondary} offsetIndex={0} halfSize={halfSize} />
          <LiquidBlob size={size} color1={c.primary} color2={c.accent} offsetIndex={1} halfSize={halfSize} />
          <LiquidBlob size={size} color1={c.secondary} color2={c.primary} offsetIndex={2} halfSize={halfSize} />
        </View>
        {Platform.OS !== 'web' && (
          <BlurView intensity={40} style={[StyleSheet.absoluteFill, { borderRadius: halfSize }]} tint="light" />
        )}
      </Animated.View>

      <Animated.View style={[styles.orbCore, { width: size, height: size, borderRadius: halfSize }, orbStyle]}>
        <LinearGradient
          colors={[c.primary, c.secondary]}
          start={{ x: 0.2, y: 0 }}
          end={{ x: 0.8, y: 1 }}
          style={[StyleSheet.absoluteFill, { borderRadius: halfSize }]}
        />
        <View style={[StyleSheet.absoluteFill, { borderRadius: halfSize }, styles.coreShine]}>
          <LinearGradient
            colors={['rgba(255,255,255,0.3)', 'transparent']}
            style={[StyleSheet.absoluteFill, { borderRadius: halfSize, top: 0, left: 0, right: 0, height: '50%' }]}
          />
        </View>
      </Animated.View>

      <View style={[styles.centerIcon, { width: size * 0.3, height: size * 0.3, borderRadius: size * 0.15 }]}>
        <LinearGradient
          colors={['rgba(255,255,255,0.35)', 'rgba(255,255,255,0.1)']}
          style={StyleSheet.absoluteFill}
          start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
        />
      </View>

      {particleStyles.map((style, i) => (
        <Animated.View key={`particle-${i}`} style={style} />
      ))}

      {isListening && (
        <View style={[styles.listeningRing, { width: size * 0.28, height: size * 0.28, borderRadius: size * 0.14, borderColor: c.primary + '80' }]} />
      )}
    </View>
  );
}

function LiquidBlob({ size, color1, color2, offsetIndex, halfSize }) {
  const offset = useSharedValue(0);

  useEffect(() => {
    const durations = [4000, 5000, 3500];
    offset.value = withRepeat(withTiming(1, { duration: durations[offsetIndex] || 4000, easing: Easing.inOut(Easing.sin) }), -1, true);
  }, []);

  const blobStyle = useAnimatedStyle(() => {
    const angle = offset.value * Math.PI * 2 + offsetIndex * 2.1;
    const dist = size * (0.15 + offsetIndex * 0.04);
    const x = Math.cos(angle) * dist;
    const y = Math.sin(angle * 0.7) * dist * 0.6;
    const s = 0.6 + 0.15 * Math.sin(offset.value * Math.PI * 2 + offsetIndex);
    return {
      width: size * 0.55,
      height: size * 0.55,
      borderRadius: size * 0.275,
      position: 'absolute',
      left: halfSize - size * 0.275 + x,
      top: halfSize - size * 0.275 + y,
      transform: [{ scale: s }],
    };
  });

  return (
    <Animated.View style={blobStyle}>
      <LinearGradient
        colors={[color1, color2]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={[StyleSheet.absoluteFill, { borderRadius: size * 0.275, opacity: 0.7 }]}
      />
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  wrapper: {
    position: 'absolute',
    top: '50%',
    left: '50%',
    alignItems: 'center',
    justifyContent: 'center',
  },
  liquidContainer: {
    position: 'absolute',
    overflow: 'hidden',
  },
  orbCore: {
    position: 'absolute',
    overflow: 'hidden',
    shadowColor: '#14B8A6',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.4,
    shadowRadius: 20,
    elevation: 10,
  },
  coreShine: {
    zIndex: 2,
  },
  centerIcon: {
    position: 'absolute',
    alignItems: 'center',
    justifyContent: 'center',
    borderWidth: 1,
    borderColor: 'rgba(255,255,255,0.2)',
  },
  listeningRing: {
    position: 'absolute',
    borderWidth: 2,
  },
});
