import React, { useRef, useEffect } from 'react';
import { View, StyleSheet, Animated, Dimensions, Platform } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { useTheme } from '../context/ThemeContext';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

export default function AuroraBackground({ children, style, intensity = 1 }) {
  const { colors } = useTheme();
  const anim1 = useRef(new Animated.Value(0)).current;
  const anim2 = useRef(new Animated.Value(0)).current;
  const anim3 = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    const createAnim = (anim, duration) => Animated.loop(
      Animated.sequence([
        Animated.timing(anim, { toValue: 1, duration, useNativeDriver: true }),
        Animated.timing(anim, { toValue: 0, duration, useNativeDriver: true }),
      ])
    );
    createAnim(anim1, 6000).start();
    createAnim(anim2, 8000).start();
    createAnim(anim3, 10000).start();
  }, []);

  const interpolateTranslate = (anim, range) => anim.interpolate({
    inputRange: [0, 1], outputRange: range,
  });

  return (
    <View style={[styles.container, { backgroundColor: colors.background }, style]}>
      <Animated.View style={[styles.blob, {
        width: SCREEN_WIDTH * 0.7, height: SCREEN_WIDTH * 0.7,
        borderRadius: SCREEN_WIDTH * 0.35,
        backgroundColor: colors.aurora1,
        top: -SCREEN_WIDTH * 0.2, left: -SCREEN_WIDTH * 0.15,
        transform: [{
          translateX: interpolateTranslate(anim1, [0, SCREEN_WIDTH * 0.15]),
        }, {
          translateY: interpolateTranslate(anim1, [0, SCREEN_HEIGHT * 0.08]),
        }],
      }]} />
      <Animated.View style={[styles.blob, {
        width: SCREEN_WIDTH * 0.5, height: SCREEN_WIDTH * 0.5,
        borderRadius: SCREEN_WIDTH * 0.25,
        backgroundColor: colors.aurora2,
        top: SCREEN_HEIGHT * 0.1, right: -SCREEN_WIDTH * 0.1,
        transform: [{
          translateX: interpolateTranslate(anim2, [0, -SCREEN_WIDTH * 0.1]),
        }, {
          translateY: interpolateTranslate(anim2, [0, SCREEN_HEIGHT * 0.05]),
        }],
      }]} />
      <Animated.View style={[styles.blob, {
        width: SCREEN_WIDTH * 0.45, height: SCREEN_WIDTH * 0.45,
        borderRadius: SCREEN_WIDTH * 0.225,
        backgroundColor: colors.aurora3,
        bottom: SCREEN_HEIGHT * 0.15, left: SCREEN_WIDTH * 0.1,
        transform: [{
          translateX: interpolateTranslate(anim3, [0, SCREEN_WIDTH * 0.12]),
        }, {
          translateY: interpolateTranslate(anim3, [0, -SCREEN_HEIGHT * 0.06]),
        }],
      }]} />
      <Animated.View style={[styles.blob, {
        width: SCREEN_WIDTH * 0.35, height: SCREEN_WIDTH * 0.35,
        borderRadius: SCREEN_WIDTH * 0.175,
        backgroundColor: colors.aurora4,
        bottom: SCREEN_HEIGHT * 0.05, right: SCREEN_WIDTH * 0.05,
        transform: [{
          translateX: interpolateTranslate(anim1, [0, -SCREEN_WIDTH * 0.08]),
        }, {
          translateY: interpolateTranslate(anim1, [0, SCREEN_HEIGHT * 0.04]),
        }],
      }]} />
      <LinearGradient
        colors={['transparent', colors.background]}
        style={styles.fadeBottom}
        pointerEvents="none"
      />
      <View style={styles.content}>
        {children}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, position: 'relative' },
  blob: { position: 'absolute', opacity: 0.6 },
  fadeBottom: {
    position: 'absolute', bottom: 0, left: 0, right: 0, height: 120,
  },
  content: { flex: 1, zIndex: 2 },
});
